// The search indexer reads the outbox. Every write to messages adds an outbox row in the same transaction.
const test = require('node:test');
const assert = require('node:assert');
const { tables } = require('../src/db');
const messages = require('../src/messages');

test('send and remove each write an outbox row', () => {
  const m = messages.send('general', 'u1', 'hello');
  messages.remove('general', m.id);
  assert.deepStrictEqual(tables.outbox.map((e) => e.type), ['message.created', 'message.deleted']);
});

